Date: Mon, 2 Mar 2020 00:56:33 +0100
Subject: [PATCH] [CONSRV] Fix a corruption of the CONSRV memory when
 converting read input events back to ANSI.

This fixes a 6-year old copy-paste bug introduced by commit b47d51c6 (r64004).

diff --git a/win32ss/user/winsrv/consrv/coninput.c b/win32ss/user/winsrv/consrv/coninput.c
index 8c2e0e82adb..b4b3061e1a3 100644
--- a/win32ss/user/winsrv/consrv/coninput.c
+++ b/win32ss/user/winsrv/consrv/coninput.c
@@ -564,9 +564,10 @@ ReadInputBuffer(IN PGET_INPUT_INFO InputInfo,
             /* Now translate everything to ANSI */
             if (!GetInputRequest->Unicode)
             {
-                for (; NumEventsRead > 0; --NumEventsRead)
+                ULONG i;
+                for (i = 0; i < NumEventsRead; ++i)
                 {
-                    ConioInputEventToAnsi(InputBuffer->Header.Console, --InputRecord);
+                    ConioInputEventToAnsi(InputBuffer->Header.Console, &InputRecord[i]);
                 }
             }
         }
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by a copy-paste error in the loop structure that processed input events, where a decrementing loop was used instead of an incrementing loop. This led to incorrect memory access and potential corruption of the CONSRV memory when converting read input events back to ANSI format.

        Commit message:
        [CONSRV] Fix a corruption of the CONSRV memory when
 converting read input events back to ANSI.

This fixes a 6-year old copy-paste bug introduced by commit b47d51c6 (r64004).  

        Patch:
                               OUT PULONG NumEventsRead OPTIONAL);
 static NTSTATUS
 ReadInputBuffer(IN PGET_INPUT_INFO InputInfo,
                 IN PCSR_API_MESSAGE ApiMessage,
                 IN BOOLEAN CreateWaitBlock OPTIONAL)
 {
     NTSTATUS Status;
     PCONSOLE_GETINPUT GetInputRequest = &((PCONSOLE_API_MESSAGE)ApiMessage)->Data.GetInputRequest;
     PCONSOLE_INPUT_BUFFER InputBuffer = InputInfo->InputBuffer;
     ULONG NumEventsRead;

     PINPUT_RECORD InputRecord;

     /*
      * For optimization purposes, Windows (and hence ReactOS, too, for
      * compatibility reasons) uses a static buffer if no more than five
      * input records are read. Otherwise a new buffer is used.
      * The client-side expects that we know this behaviour.
      */
     if (GetInputRequest->NumRecords <= sizeof(GetInputRequest->RecordStaticBuffer)/sizeof(INPUT_RECORD))
     {
         /*
          * Adjust the internal pointer, because its old value points to
          * the static buffer in the original ApiMessage structure.
          */
         // GetInputRequest->RecordBufPtr = GetInputRequest->RecordStaticBuffer;
         InputRecord = GetInputRequest->RecordStaticBuffer;
     }
     else
     {
         InputRecord = GetInputRequest->RecordBufPtr;
     }

     NumEventsRead = 0;
     Status = ConDrvGetConsoleInput(InputBuffer->Header.Console,
                                    InputBuffer,
                                    (GetInputRequest->Flags & CONSOLE_READ_KEEPEVENT) != 0,
                                    (GetInputRequest->Flags & CONSOLE_READ_CONTINUE ) == 0,
                                    InputRecord,
                                    GetInputRequest->NumRecords,
                                    &NumEventsRead);

     if (Status == STATUS_PENDING)
     {
         /* We haven't completed a read, so start a wait */
         return WaitBeforeReading(InputInfo,
                                  ApiMessage,
                                  ReadInputBufferThread,
                                  CreateWaitBlock);
     }
     else
     {
         /*
          * We read all what we wanted. Set the number of events read and
          * return the error code we were given.
          */
         GetInputRequest->NumRecords = NumEventsRead;

         if (NT_SUCCESS(Status))
         {
             /* Now translate everything to ANSI */
             if (!GetInputRequest->Unicode)
             {
-                for (; NumEventsRead > 0; --NumEventsRead)
+                ULONG i;
+                for (i = 0; i < NumEventsRead; ++i)
                 {
-                    ConioInputEventToAnsi(InputBuffer->Header.Console, --InputRecord);
+                    ConioInputEventToAnsi(InputBuffer->Header.Console, &InputRecord[i]);
                 }
             }
         }

         return Status;
         // return STATUS_SUCCESS;
     }
 }



